#' RD Honest Confidence Intervals
#'
#' 
#' @param data .
#' @param outcome .
#' @param running .
#' @param treatment .
#' @param cutoff .
#' @param M .
#' @param optCriterion .
#' @param kernel .
#' @param seMethod .
#' @param level .
#' @param hManual .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$est} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$spec} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$est$asDF}
#'
#' \code{as.data.frame(results$est)}
#'
#' @export
rdhonest <- function(
    data,
    outcome,
    running,
    treatment,
    cutoff = 0,
    M = 0,
    optCriterion = "MSE",
    kernel = "triangular",
    seMethod = "nn",
    level = 95,
    hManual = 0,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("rdhonest requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(running)) running <- jmvcore::resolveQuo(jmvcore::enquo(running))
    if ( ! missing(treatment)) treatment <- jmvcore::resolveQuo(jmvcore::enquo(treatment))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(running), running, NULL),
            `if`( ! missing(treatment), treatment, NULL))


    options <- rdhonestOptions$new(
        outcome = outcome,
        running = running,
        treatment = treatment,
        cutoff = cutoff,
        M = M,
        optCriterion = optCriterion,
        kernel = kernel,
        seMethod = seMethod,
        level = level,
        hManual = hManual,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- rdhonestClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

